import { RoutePlanResponse, type RoutePlanRequest } from "@/schema/route";
import { haversine } from "@/server/geo";
import aluvaVyttila from "./aluva-vyttila.json";
import mgroadKakkanad from "./mgroad-kakkanad.json";
import kalamasseryInfopark from "./kalamassery-infopark.json";

/** Hand-checked sample responses generated by scripts/make-fixtures.ts. Clearly flagged as mock. */
export const FIXTURES: RoutePlanResponse[] = [aluvaVyttila, mgroadKakkanad, kalamasseryInfopark].map((f) =>
  RoutePlanResponse.parse(f),
);

/** Max distance (m) between a fixture's A/B and the requested A/B for it to count as a match. */
const MATCH_RADIUS_M = 1500;

/** A saved sample for this exact trip, or null when none is close enough (caller then plans for real). */
export function pickFixture(req: RoutePlanRequest): RoutePlanResponse | null {
  const near = (f: RoutePlanResponse) =>
    haversine(f.origin.location, req.origin.location) < MATCH_RADIUS_M &&
    haversine(f.destination.location, req.destination.location) < MATCH_RADIUS_M;
  const best = FIXTURES.find(near);
  if (!best) return null;
  return {
    ...best,
    mock: true,
    dataWarnings: [
      "MOCK DATA: this is a saved sample journey, not a plan for your exact locations (USE_MOCK_ROUTES=true).",
      ...(best.dataWarnings ?? []),
    ],
  };
}
